using System.Numerics;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization to process multiple elements per iteration.
    /// </summary>
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count)
        {
            var vectors = MemoryMarshal.Cast<float, Vector<float>>(values);
            var vMin = vectors[0];
            var vMax = vectors[0];

            for (int v = 1; v < vectors.Length; v++)
            {
                vMin = Vector.Min(vMin, vectors[v]);
                vMax = Vector.Max(vMax, vectors[v]);
            }

            // Reduce vector lanes to scalar min/max
            float min = vMin[0];
            float max = vMax[0];
            for (int lane = 1; lane < Vector<float>.Count; lane++)
            {
                if (vMin[lane] < min) min = vMin[lane];
                if (vMax[lane] > max) max = vMax[lane];
            }

            // Handle remaining elements not covered by full vectors
            i = vectors.Length * Vector<float>.Count;
            for (; i < values.Length; i++)
            {
                if (values[i] < min) min = values[i];
                if (values[i] > max) max = values[i];
            }

            return (min, max);
        }

        // Scalar fallback
        {
            float min = values[0];
            float max = values[0];
            for (i = 1; i < values.Length; i++)
            {
                if (values[i] < min) min = values[i];
                if (values[i] > max) max = values[i];
            }
            return (min, max);
        }
    }
}

